def fruit_distribution(s, n):
    def extract_fruits_count(s):
        apples, oranges = 0, 0
        for word in s.split():
            if word.isdigit():
                if "apple" in s:
                    apples = int(word)
                elif "orange" in s:
                    oranges = int(word)
        return apples, oranges

    def calculate_mango_count(s, n):
        apples, oranges = extract_fruits_count(s)
        total_fruits = apples + oranges
        mango_count = n - total_fruits
        return mango_count

    return calculate_mango_count(s, n)

