    def rotate_alphabet(char):
        if char.islower():
            return chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
        elif char.isupper():
            return chr((ord(char) - ord('A') + 4) % 26 + ord('A'))
        else:
            return char

    return ''.join([rotate_alphabet(c) for c in s])

